  // ------------------------------------------------------------ the language packs (marsh_text_pt.js … _ja.js): MHFTXT.add(lang, pack)
  // pack: { CAST, LINES, DEMO, FIGHT, NAMES: { key: text }, LORE: text, MARKS: { key: [...] }, CARDS: { key: { ex, note } },
  //         TIPS: { kind: text }, SPECIES: {...}, TASKS: { key: { frame, chips, model, want, alt, mood, real, main, … } } }
  function add(l, pack) {
    if (!pack) return;
    const tabs = { CAST, LINES, DEMO, FIGHT, NAMES };
    for (const [tn, tab] of Object.entries(tabs)) for (const [k, t] of Object.entries(pack[tn] || {})) if (tab[k]) tab[k][l] = t; else console.warn('[marsh future] ' + l + ': no ' + tn + '.' + k);
    if (pack.LORE) LORE[l] = pack.LORE;
    for (const [k, m] of Object.entries(pack.MARKS || {})) (MARKS[k] || (MARKS[k] = {}))[l] = m;
    for (const [k, c] of Object.entries(pack.CARDS || {})) if (CARDS[k]) CARDS[k][l] = c;
    for (const [k, t] of Object.entries(pack.TIPS || {})) (TIPS[k] || (TIPS[k] = {}))[l] = t;
    if (pack.SPECIES) SPECIES[l] = pack.SPECIES;
    const field = (T0, f, v) => { if (f === 'model') { T0.model[l] = v; return; } if (f === 'tips') { for (const [kk, tt] of Object.entries(v)) { T0.tips = T0.tips || {}; (T0.tips[kk] || (T0.tips[kk] = {}))[l] = tt; } return; } (T0[f] || (T0[f] = {}))[l] = v; };
    for (const [k, P] of Object.entries(pack.TASKS || {})) { const T0 = TASKS[k]; if (!T0) { console.warn('[marsh future] ' + l + ': no task ' + k); continue; } for (const [f, v] of Object.entries(P)) field(T0, f, v); }
  }
  return { CAST, LINES, DEMO, MARKS, CARDS, TIPS, TASKS, ROOMS, FIGHT, SPECIES, NAMES, LORE, WORDS, add };
